89	
90		mustSample(t, s, "SN", "P", at(2, 0), Measurement{Item: zeroItem, Value: 7})
91		if _, err := s.Confirm("SN"); !errors.Is(err, ErrMissingLimit) {
92			t.Fatalf("另一组缺上限应拒绝，got %v", err)
93		}
94		list, err := s.ListByPoint("P")
95		if err != nil || len(list) != 1 {
96			t.Fatalf("list: %+v err=%v", list, err)
97		}
98		if got := list[0]; got.Status != StatusPending || got.Results != nil || got.Exceeded {
99			t.Fatalf("拒绝后必须保持待判定且无部分结果: %+v", got)
100		}
101		if _, ok, err := s.LatestResult("P"); err != nil || ok {
102			t.Fatalf("另一组不应出现已确认结果 ok=%v err=%v", ok, err)
103		}
104	
105		// 被拒绝的确认不影响已有组的判定
106		mustSample(t, s, "SZ", zeroPoint, at(2, 0), Measurement{Item: "B", Value: 7})
107		rz, err := s.Confirm("SZ")
108		if err != nil || rz.Exceeded || rz.Results[0].Limit != 10 {
109			t.Fatalf("已有组判定受影响: %+v err=%v", rz, err)
110		}
