113	// 两组各有多版限值时，独立选择采样当时已生效的最近一版；
114	// 另一组更晚生效的版本不影响本组；边界时刻与等于上限的规则保持不变。
115	func TestLimitGroupVersionsIndependent(t *testing.T) {
116		s, _ := open(t)
117		zeroPoint := "P\x00A"
118		zeroItem := "A\x00B"
119		mustPoint(t, s, zeroPoint, "带零编号")
120		mustPoint(t, s, "P", "普通编号")
