122		// zeroPoint/B：10@9/1、20@9/10
123		mustLimit(t, s, zeroPoint, "B", 10, at(1, 0))
124		mustLimit(t, s, zeroPoint, "B", 20, at(10, 0))
125		// P/zeroItem：5@9/1、50@9/20（另一组更晚的 20@9/10 与本组互不干涉）
126		mustLimit(t, s, "P", zeroItem, 5, at(1, 0))
127		mustLimit(t, s, "P", zeroItem, 50, at(20, 0))
128	
129		// 9/10 采样：zeroPoint 组恰好生效 20（边界用新版，等于上限达标）
130		mustSample(t, s, "SZ", zeroPoint, at(10, 0), Measurement{Item: "B", Value: 20})
131		rz, err := s.Confirm("SZ")
132		if err != nil {
133			t.Fatalf("Confirm SZ: %v", err)
134		}
135		if rz.Exceeded || rz.Results[0].Limit != 20 ||
136			!rz.Results[0].LimitEffective.Equal(at(10, 0)) {
137			t.Fatalf("边界时刻应用该版且等于上限达标: %+v", rz.Results[0])
138		}
139	
140		// 9/15 采样：P 组只能用 5（本组的 50 尚未生效，另一组的 20 不能借用）
141		mustSample(t, s, "SN", "P", at(15, 0), Measurement{Item: zeroItem, Value: 7})
142		rn, err := s.Confirm("SN")
143		if err != nil {
144			t.Fatalf("Confirm SN: %v", err)
145		}
146		if !rn.Exceeded || rn.Results[0].Limit != 5 ||
147			!rn.Results[0].LimitEffective.Equal(at(1, 0)) {
148			t.Fatalf("本组不能受另一组版本影响: %+v", rn.Results[0])
149		}
150	
151		// 同组同一时刻（不同时区表示）仍报重复，且不覆盖原值
152		cst5 := time.Date(2026, 9, 10, 8, 0, 0, 0, time.FixedZone("CST", 8*3600))
153		if _, err := s.SetLimit(zeroPoint, "B", 99, cst5); !errors.Is(err, ErrDuplicateLimitTime) {
154			t.Fatalf("同组同一时刻换时区表示应报重复, got %v", err)
155		}
156		mustSample(t, s, "SZ2", zeroPoint, at(11, 0), Measurement{Item: "B", Value: 25})
157		rz2, err := s.Confirm("SZ2")
158		if err != nil || rz2.Results[0].Limit != 20 || !rz2.Exceeded {
159			t.Fatalf("被拒绝的登记不得覆盖原值: %+v err=%v", rz2.Results[0], err)
160		}
161		// 另一组记录也不受这次拒绝影响
162		if got := s.limits[limitGroup{pointID: "P", item: zeroItem}]; len(got) != 2 {
163			t.Fatalf("拒绝操作改动了另一组记录: %+v", got)
164		}
165	}
