167	// 旧版本曾把限值按 "pointID + U+0000 + item" 单键落盘，
168	// 包含 U+0000 的不同组合会共用同一个键。重新打开旧文件时必须按每条
169	// 限值自身的采样点与项目重新分组，已确认样品的原结论与所用限值保持不变。
170	func TestLimitGroupReloadOldCollidedFile(t *testing.T) {
171		dir := t.TempDir()
172		zeroPoint := "P\x00A"
173		zeroItem := "A\x00B"
174		eff := at(1, 0)
175	
176		// 手工构造旧格式文件：两组限值落在同一个碰撞键下，
177		// 但每条记录各自带着正确的 pointId/item。
178		oldKey := zeroPoint + "\x00" + "B" // 旧算法的键，与 "P" + "\x00" + zeroItem 相同
179		if oldKey != "P"+"\x00"+zeroItem {
180			t.Fatal("test setup: 两个组合应拼出同一个旧键")
181		}
182		old := diskState{
183			Points: map[string]SamplingPoint{
184				zeroPoint: {ID: zeroPoint, Name: "带零编号"},
185				"P":       {ID: "P", Name: "普通编号"},
186			},
187			Limits: map[string][]Limit{
188				oldKey: {
189					{PointID: zeroPoint, Item: "B", Value: 10, Effective: eff},
190					{PointID: "P", Item: zeroItem, Value: 5, Effective: eff},
191				},
192			},
193			Samples: map[string]*Sample{
194				"SN": {
195					ID: "SN", PointID: "P", SampledAt: at(2, 0),
196					Measurements: []Measurement{{Item: zeroItem, Value: 7}},
197					Status:       StatusConfirmed, Exceeded: true,
198					Results: []ItemResult{{
199						Item: zeroItem, Value: 7, Limit: 5,
200						LimitEffective: eff, Exceeded: true,
201					}},
202				},
203			},
204		}
205		data, err := json.MarshalIndent(old, "", "  ")
206		if err != nil {
207			t.Fatalf("marshal old file: %v", err)
208		}
209		if err := os.WriteFile(filepath.Join(dir, "water-data.json"), data, 0o644); err != nil {
210			t.Fatalf("write old file: %v", err)
211		}
212	
213		s, err := Open(dir)
214		if err != nil {
215			t.Fatalf("Open old file: %v", err)
216		}
217		defer s.Close()
218	
219		if got := s.limits[limitGroup{pointID: zeroPoint, item: "B"}]; len(got) != 1 || got[0].Value != 10 {
220			t.Fatalf("旧文件重新分组失败（zeroPoint 组）: %+v", got)
221		}
222		if got := s.limits[limitGroup{pointID: "P", item: zeroItem}]; len(got) != 1 || got[0].Value != 5 {
223			t.Fatalf("旧文件重新分组失败（P 组）: %+v", got)
224		}
225	
226		// 已确认样品保留原结论与所用限值，不自动重新判定
227		kept, err := s.Confirm("SN")
228		if err != nil {
229			t.Fatalf("Confirm kept sample: %v", err)
230		}
231		if r := kept.Results[0]; !kept.Exceeded || r.Item != zeroItem ||
232			r.Value != 7 || r.Limit != 5 || !r.LimitEffective.Equal(eff) {
233			t.Fatalf("已确认样品结论被改动: %+v", kept)
234		}
235	
236		// 同一时刻两组各自再登记仍互不冲突；同组重复仍拒绝
237		if _, err := s.SetLimit(zeroPoint, "B", 11, at(5, 0)); err != nil {
238			t.Fatalf("两组独立补录应成功: %v", err)
239		}
240		if _, err := s.SetLimit("P", zeroItem, 6, at(5, 0)); err != nil {
241			t.Fatalf("两组独立补录应成功: %v", err)
242		}
243		if _, err := s.SetLimit(zeroPoint, "B", 12, eff); !errors.Is(err, ErrDuplicateLimitTime) {
244			t.Fatalf("同组同一时刻仍应报重复, got %v", err)
245		}
246	
247		// 再次落盘并重新打开，归属仍然正确
248		if err := s.Close(); err != nil {
249			t.Fatalf("Close: %v", err)
250		}
251		s2, err := Open(dir)
252		if err != nil {
253			t.Fatalf("reopen: %v", err)
254		}
255		defer s2.Close()
256		if got := s2.limits[limitGroup{pointID: zeroPoint, item: "B"}]; len(got) != 2 {
257			t.Fatalf("重开后版本丢失或串组: %+v", got)
258		}
259		if got := s2.limits[limitGroup{pointID: "P", item: zeroItem}]; len(got) != 2 {
260			t.Fatalf("重开后版本丢失或串组: %+v", got)
261		}
262	}
