251	
252		// 任一内容不同则拒绝
253		cases := []struct {
254			point string
255			at    time.Time
256			ms    []Measurement
257		}{
258			{"P1", at(2, 0), []Measurement{{Item: "pH", Value: 7}, {Item: "COD", Value: 20}}},
